-- Cached CCTV health checks used by the question-selection pool.
DROP TABLE IF EXISTS `cctv_health`;
CREATE TABLE `cctv_health` (
  `cctv_id` int unsigned NOT NULL,
  `is_usable` tinyint(1) NOT NULL,
  `quality_score` decimal(5,2) DEFAULT NULL,
  `checked_at` datetime(6) NOT NULL,
  `failure_reason` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`cctv_id`),
  KEY `cctv_health_usable_checked` (`is_usable`,`checked_at`,`quality_score`),
  CONSTRAINT `cctv_health_cctv_fk` FOREIGN KEY (`cctv_id`) REFERENCES `cctv` (`ID`) ON DELETE CASCADE,
  CONSTRAINT `cctv_health_usable_check` CHECK ((`is_usable` in (0,1))),
  CONSTRAINT `cctv_health_quality_check` CHECK ((`quality_score` is null) or (`quality_score` between 0 and 100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

